import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

transposed_conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

// Naive transposed convolution kernel supporting stride, padding, and output_padding.
// Groups are assumed to be 1 for simplicity. Bias is optional (may be nullptr).
// Weight layout is [in_channels, out_channels, kernel_size, kernel_size].
// Input layout is [N, inC, inH, inW], output layout is [N, outC, outH, outW].
__global__ void transposed_conv2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int N,
    int inC,
    int inH,
    int inW,
    int outC,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    int outH,
    int outW)
{
    // Grid/z dimension lumps batch (N) and outC together:
    int tile_idx = blockIdx.z;
    int n = tile_idx / outC;
    int oc = tile_idx % outC;

    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    if (ow >= outW || oh >= outH) {
        return;
    }

    // Compute output index
    int out_index = n * outC * outH * outW + oc * outH * outW + oh * outW + ow;

    // Accumulator for the result
    float val = 0.0f;

    // Naive loop over inC, kernel height, kernel width
    for (int ic = 0; ic < inC; ic++) {
        for (int kh = 0; kh < kernel_size; kh++) {
            for (int kw = 0; kw < kernel_size; kw++) {
                // Compute corresponding input location
                int in_h = oh + padding - kh;
                int in_w = ow + padding - kw;

                // Must check stride alignment
                if ((in_h % stride == 0) && (in_w % stride == 0)) {
                    int ih = in_h / stride;
                    int iw = in_w / stride;
                    if (ih >= 0 && ih < inH && iw >= 0 && iw < inW) {
                        // Weight offset:
                        // weight shape: (inC, outC, kH, kW)
                        // Flatten index = ic * outC * kH * kW + oc * kH * kW + kh * kW + kw
                        int w_idx = (((ic * outC + oc) * kernel_size) + kh) * kernel_size + kw;
                        float w_val = weight[w_idx];

                        // Input offset:
                        // input shape: (N, inC, inH, inW)
                        // Flatten index = n * inC * inH * inW + ic * inH * inW + ih * inW + iw
                        int in_idx = n * inC * inH * inW + ic * inH * inW + ih * inW + iw;
                        float i_val = input[in_idx];

                        val += i_val * w_val;
                    }
                }
            }
        }
    }

    // Add bias if present
    if (bias != nullptr) {
        val += bias[oc];
    }

    output[out_index] = val;
}

torch::Tensor transposed_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias_opt,
    int stride,
    int padding,
    int output_padding)
{
    // Get sizes
    int N = input.size(0);
    int inC = input.size(1);
    int inH = input.size(2);
    int inW = input.size(3);

    int outC = weight.size(1);
    int kernel_size = weight.size(2);

    // Compute output spatial size
    int outH = (inH - 1) * stride - 2 * padding + kernel_size + output_padding;
    int outW = (inW - 1) * stride - 2 * padding + kernel_size + output_padding;

    // Allocate output
    auto out_options = input.options();
    auto output = torch::zeros({N, outC, outH, outW}, out_options);

    const float* input_ptr = input.data_ptr<float>();
    const float* weight_ptr = weight.data_ptr<float>();
    const float* bias_ptr = nullptr;
    if (bias_opt.has_value()) {
        bias_ptr = bias_opt.value().data_ptr<float>();
    }
    float* output_ptr = output.data_ptr<float>();

    // Configure block/grid
    dim3 block(16, 16);
    dim3 grid((outW + block.x - 1) / block.x,
              (outH + block.y - 1) / block.y,
              N * outC);

    // Launch kernel
    transposed_conv2d_kernel<<<grid, block>>>(
        input_ptr,
        weight_ptr,
        bias_ptr,
        output_ptr,
        N,
        inC,
        inH,
        inW,
        outC,
        kernel_size,
        stride,
        padding,
        output_padding,
        outH,
        outW
    );

    // Synchronize
    cudaDeviceSynchronize();

    return output;
}
""";

transposed_conv2d_cpp_source = r"""
torch::Tensor transposed_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias_opt,
    int stride,
    int padding,
    int output_padding);
""";

# Compile and load the inline CUDA code
_transposed_conv2d = load_inline(
    name="transposed_conv2d_op",
    cpp_sources=transposed_conv2d_cpp_source,
    cuda_sources=transposed_conv2d_source,
    functions=["transposed_conv2d_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Custom transposed convolution using a naive CUDA kernel for demonstration.
    Supports stride, padding, and output_padding. Groups are assumed to be 1.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super(ModelNew, self).__init__()
        # For simplicity, we assume groups=1
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        # PyTorch's ConvTranspose2d stores weights as (in_channels, out_channels // groups, kH, kW)
        # We'll do the same shape here.
        self.weight = nn.Parameter(
            torch.randn(in_channels, out_channels, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _transposed_conv2d.transposed_conv2d_cuda(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride,
            self.padding,
            self.output_padding
        )
